package com.gymflow.membership; import jakarta.validation.Valid; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/gyms/{gymId}/membership-plans") public class MembershipPlanController {private final MembershipPlanService service;public MembershipPlanController(MembershipPlanService s){service=s;}@PostMapping @ResponseStatus(HttpStatus.CREATED) public MembershipPlanResponse create(@PathVariable UUID gymId,@Valid @RequestBody MembershipPlanRequest r){return service.create(gymId,r);}@GetMapping public List<MembershipPlanResponse> findAll(@PathVariable UUID gymId){return service.findAll(gymId);}}
